/* Extracted from the customer workflow; existing business globals and stored records stay compatible. */
'use strict';
const RULES=[['primary','主客户判定规则','layers','blue','P-RC-02'],['intercept','前置拦截规则','shield','purple','P-RC-03'],['deposit','预约金有效期','clock','orange','P-RC-04'],['arbitration','订单仲裁规则','flow','cyan','P-RC-05']];
function renderRuleDrawers(content){let root=$('#mergeDrawers');syncDrawerLayer(root,'merge',content?mergeOuterDrawer(content):'');syncDrawerLayer(root,'arb',content&&arbEditing?arbDrawer():'');syncDrawerLayer(root,'history',historyProfileId?mergeHistoryDrawer():'');syncDrawerInteraction()}
function mergeModuleSnapshots(p){let c=p.config;return {
 '基本信息':{'规则名称':p.name,'默认规则':p.isDefault,'合并后冷静期（小时）':c.threshold.hours,'冷静期内限制操作':['退款操作','白条充值 / 消耗','资产变更','手动修改客户基本信息'].filter((x,i)=>c.threshold.limits[i]),'快照保留期限（月）':c.threshold.months},
 '主客户判定规则':c.primary.map((r,i)=>({'序号':i+1,'判定条件':r.name,'启用':r.enabled,'双方均满足':r.conflict})),
 '前置拦截规则':{'拦截条件':clone(c.intercept),'数据迁移':clone(c.migrate)},
 '预约金有效期':{'在职成员有效期（月）':c.deposit.active,'离职成员有效期（月）':c.deposit.left,'三级预约金仲裁':c.deposit.policy.rules.map((r,i)=>({'序号':i+1,'条件':r.name,'处理动作':ARB_ACTIONS[r.action]}))},
 '订单仲裁规则':{'规则':c.arbitration.rules.map((r,i)=>({'序号':i+1,'规则名称':r.name,'启用':r.enabled,'条件':clone(r.when),'执行动作':ARB_ACTIONS[r.action]})),'未命中规则时':ARB_ACTIONS[c.arbitration.fallback]}
}}
function filterRuleRows(type,q){ruleListQueries[type]=q;let root=$('#'+type+'RuleRows');if(root)Array.from(root.querySelectorAll(type==='primary'?'.priority-row':'tbody tr')).forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q.toLowerCase()))}
function ruleQueryModule(type,label){return queryModule('<div class="search">'+icon('search')+'<input aria-label="搜索'+label+'" placeholder="搜索'+label+'名称" value="'+esc(ruleListQueries[type])+'" oninput="filterRuleRows(\''+type+'\',this.value)"></div>'+btn('重置',"ruleListQueries['"+type+"']='';render()",'text'))}
function mergeProfileList(){let rows=state.mergeProfiles.filter(p=>(!mergeListQuery||p.name.includes(mergeListQuery))&&(mergeListFilter==='all'||(mergeListFilter==='default'?p.isDefault:!p.isDefault)));return queryModule('<div class="search">'+icon('search')+'<input aria-label="搜索合并规则" placeholder="搜索规则名称" value="'+esc(mergeListQuery)+'" oninput="mergeListQuery=this.value;refreshMergeProfileRows()"></div>'+select([['all','全部规则'],['default','默认规则'],['other','非默认规则']],mergeListFilter,'aria-label="默认状态" onchange="mergeListFilter=this.value;refreshMergeProfileRows()"')+btn('重置',"mergeListQuery='';mergeListFilter='all';render()"))+contentModule('合并规则','<div id="mergeProfileRows">'+mergeProfileRows(rows)+'</div>',btn('新建合并规则','openMergeEditor()','primary','plus'))}
function mergeProfileRows(rows){return table(['规则名称','默认状态','主客户判定','前置拦截','订单仲裁','更新人','更新时间','操作'],rows.map(p=>['<button class="inline-link" onclick="openMergeEditor(\''+p.id+'\')">'+esc(p.name)+'</button>',p.isDefault?badge('默认规则','blue'):badge('非默认',''),p.config.primary.filter(r=>r.enabled).length+' 项',p.config.intercept.filter(r=>r.on).length+' 项',p.config.arbitration.rules.length+' 条',esc(p.updatedBy||'张三'),'<span class="mono">'+p.updatedAt.slice(0,16)+'</span>','<div class="merge-row-actions">'+btn('编辑',"openMergeEditor('"+p.id+"')",'text')+'<button id="history-'+p.id+'" class="btn text" onclick="openMergeHistory(\''+p.id+'\')">变更历史</button>'+(!p.isDefault?btn('设为默认',"setDefaultMergeProfile('"+p.id+"')",'text')+btn('删除',"deleteMergeProfile('"+p.id+"')",'text'):'')+'</div>']))+(!rows.length?empty('暂无合并规则',''):'')+'<div class="pagination"><span>共 '+rows.length+' 条</span></div>'}
function refreshMergeProfileRows(){let rows=state.mergeProfiles.filter(p=>(!mergeListQuery||p.name.includes(mergeListQuery))&&(mergeListFilter==='all'||(mergeListFilter==='default'?p.isDefault:!p.isDefault)));$('#mergeProfileRows').innerHTML=mergeProfileRows(rows)}
function openMergeHistory(id){if(!state.mergeProfiles.some(p=>p.id===id))return;mergeEditor=null;arbEditing=null;historyProfileId=id;historyFilter={module:'',user:'',from:'',to:''};route='rules';render()}
function closeMergeHistory(){let id=historyProfileId;historyProfileId=null;render();focusAfterDrawerClose('#history-'+id)}
function mergeHistoryDrawer(){let p=state.mergeProfiles.find(p=>p.id===historyProfileId);if(!p)return '';return '<div class="merge-drawer-backdrop" onclick="if(event.target===this&&!this.dataset.closing&&!document.querySelector(\'#modal>[data-overlay-layer]\'))closeMergeHistory()"><section class="merge-drawer" id="mergeHistoryPanel" role="dialog" aria-modal="true" aria-label="变更历史"><header class="merge-drawer-head"><h2>变更历史 · '+esc(p.name)+'</h2><button class="icon-btn" aria-label="关闭变更历史" onclick="closeMergeHistory()">'+icon('close')+'</button></header><div class="merge-drawer-body" data-drawer-scroll="history">'+historyPage()+'</div><footer class="merge-drawer-foot"><div class="actions">'+btn('关闭','closeMergeHistory()')+'</div></footer></section></div>'}
function openMergeEditor(id){historyProfileId=null;let p=state.mergeProfiles.find(p=>p.id===id);mergeDrawerFocus=document.activeElement;mergeEditor=p?{id:p.id,name:p.name,isDefault:p.isDefault,isNew:false}:{id:'merge-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,5),name:'',isDefault:!state.mergeProfiles.length,isNew:true};configDraft=clone(p?p.config:defaults);configDraft=normalizeMergeConfiguration(configDraft);arbEditing=null;arbListQuery='';depositPolicyQuery='';historyFilter={module:'',user:'',from:'',to:''};mergeRuleTab='base';route='rule-base';ruleListQueries={primary:'',intercept:''};render();$('#mergeProfileName')?.focus()}
function closeMergeEditor(){mergeEditor=null;arbEditing=null;configDraft=clone(state.config);route='rules';render();focusAfterDrawerClose('#main .content-module .actions button')}
function saveMergeProfile(){if(!mergeEditor)return;let old=state.mergeProfiles.find(p=>p.id===mergeEditor.id),profile={id:mergeEditor.id,name:mergeEditor.name.trim()||'合并规则 '+(state.mergeProfiles.length+1),isDefault:!!mergeEditor.isDefault,version:(old?.version||0)+1,updatedAt:now(),updatedBy:'张三',moduleHistorySamplesVersion:1,config:clone(configDraft)};
 let wasDefault=state.mergeProfiles.find(p=>p.isDefault);if(wasDefault?.id===profile.id||!wasDefault)profile.isDefault=true;
 let before=old?mergeModuleSnapshots(old):{},after=mergeModuleSnapshots(profile);Object.keys(after).forEach(module=>{if(JSON.stringify(before[module])!==JSON.stringify(after[module]))state.history.unshift({time:profile.updatedAt,user:'张三',module,profileId:profile.id,summary:(old?'修改':'新建')+module+'配置',before:before[module]||{},after:after[module]})});
 if(old)state.mergeProfiles[state.mergeProfiles.indexOf(old)]=profile;else state.mergeProfiles.push(profile);if(profile.isDefault)state.mergeProfiles.forEach(p=>p.isDefault=p.id===profile.id);state.config=clone(state.mergeProfiles.find(p=>p.isDefault).config);persist();closeMergeEditor();toast('合并规则已保存')
}
function setDefaultMergeProfile(id){let p=state.mergeProfiles.find(p=>p.id===id);if(!p)return;state.mergeProfiles.forEach(p=>p.isDefault=p.id===id);state.config=clone(p.config);configDraft=clone(state.config);state.history.unshift({time:now(),user:'张三',module:'合并规则',profileId:id,summary:'设为默认规则：'+p.name,before:{},after:{默认规则:p.name}});persist();render();toast('已将“'+p.name+'”设为默认规则')}
function deleteMergeProfile(id){let p=state.mergeProfiles.find(p=>p.id===id);if(!p||p.isDefault)return;modal('删除合并规则','<p>确认删除“'+esc(p.name)+'”？</p>',btn('取消','closeModal()')+btn('删除',"state.mergeProfiles=state.mergeProfiles.filter(p=>p.id!=='"+id+"');persist();closeModal();render()",'danger'))}
let depositPolicyQuery='';
function baseNumber(key,label,value,unit){return '<div class="input-with-unit"><input type="number" min="0" aria-label="'+label+'" value="'+value+'" oninput="configDraft.threshold.'+key+'=Number(this.value)"><span>'+unit+'</span></div>'}
function depositPolicyRows(){let actions=['keepMain','keepChild','keepBoth','manual','latest','earliest','valid','continue'].map(k=>[k,ARB_ACTIONS[k]]),rows=depositPolicyConfig().rules.map((r,i)=>({r,i})).filter(({r})=>!depositPolicyQuery||r.name.includes(depositPolicyQuery));return table(['序号','条件','处理动作'],rows.map(({r,i})=>['<span class="mono">'+String(i+1).padStart(2,'0')+'</span>',esc(r.name),select(actions,r.action,'aria-label="'+esc(r.name)+'处理动作" onchange="depositPolicyConfig().rules['+i+'].action=this.value"')]))+(!rows.length?empty('暂无匹配的条件',''):'')}
function refreshDepositPolicyRows(){let el=$('#depositPolicyRows');if(el)el.innerHTML=depositPolicyRows()}
function arbEditorTitle(){return (arbEditing.isNew?'新增':'编辑')+'仲裁规则'}
function arbEditorActions(){return Object.entries(ARB_ACTIONS)}
function mergeBasePage(){let existing=state.mergeProfiles.find(p=>p.id===mergeEditor.id),locked=!!existing?.isDefault,r=configDraft.threshold;return contentModule('规则信息','<div class="panel-body base-compact-form">'+field('规则名称','<input id="mergeProfileName" placeholder="输入规则名称" value="'+esc(mergeEditor.name)+'" oninput="mergeEditor.name=this.value">')+'<label class="merge-default-check base-compact-default"><input type="checkbox" aria-label="设为默认合并规则" '+(mergeEditor.isDefault?'checked':'')+' '+(locked?'disabled':'')+' onchange="mergeEditor.isDefault=this.checked">'+(locked?'当前默认规则':'设为默认规则')+'</label>'+field('合并后冷静期',baseNumber('hours','冷静期时长',r.hours,'小时'))+'<div class="field base-compact-restriction-field"><label id="baseRestrictionLabel">冷静期内限制操作</label><div class="base-compact-restrictions" role="group" aria-labelledby="baseRestrictionLabel">'+['退款操作','白条充值 / 消耗','资产变更','手动修改客户基本信息'].map((label,i)=>'<label class="check-line"><input type="checkbox" '+(r.limits[i]?'checked':'')+' onchange="configDraft.threshold.limits['+i+']=this.checked">'+label+'</label>').join('')+'</div></div><div class="base-compact-snapshot">'+field('快照保留期限',baseNumber('months','快照保留期限',r.months,'个月'))+'</div></div>')}
function mergeOuterDrawer(content){let existing=state.mergeProfiles.find(p=>p.id===mergeEditor.id),locked=!!existing?.isDefault;return '<div class="merge-drawer-backdrop" onclick="if(event.target===this&&!this.dataset.closing&&canDismissMergeBackdrop())closeMergeEditor()"><section class="merge-drawer" id="mergeOuterPanel" role="dialog" aria-modal="true" aria-label="'+(mergeEditor.isNew?'新建合并规则':'编辑合并规则')+'"><header class="merge-drawer-head"><h2>'+(mergeEditor.isNew?'新建合并规则':'编辑合并规则')+'</h2><button class="icon-btn" aria-label="关闭合并规则抽屉" onclick="closeMergeEditor()">'+icon('close')+'</button></header><div class="merge-drawer-body" data-drawer-scroll="outer">'+mergeRuleWorkspace(content)+'</div><footer class="merge-drawer-foot"><div class="actions">'+btn('取消','closeMergeEditor()')+btn('保存规则','saveMergeProfile()','primary')+'</div></footer></section></div>'}
function arbDrawer(){let r=arbCurrent();return '<div class="merge-drawer-backdrop arb-editor-backdrop" onclick="if(event.target===this&&!this.dataset.closing)arbCloseEditor()"><section class="merge-drawer arb-editor-drawer" role="dialog" aria-modal="true" aria-label="'+arbEditorTitle()+'"><header class="merge-drawer-head"><h2>'+arbEditorTitle()+'</h2><button class="icon-btn" aria-label="关闭仲裁规则抽屉" onclick="arbCloseEditor()">'+icon('close')+'</button></header><div class="merge-drawer-body" data-drawer-scroll="arb">'+field('规则名称','<input id="arbRuleName" aria-label="仲裁规则名称" placeholder="输入仲裁规则名称" value="'+esc(r.name)+'" oninput="arbCurrent().name=this.value">')+'<div class="merge-field-row"><span>启用状态</span>'+switcher(r.enabled,'arbCurrent().enabled=this.checked','启用当前仲裁规则')+'</div><div class="arb-section-title"><h3>满足以下条件时</h3></div>'+arbRenderGroup(r.when,'',0)+'<div class="arb-section-title" style="margin-top:24px"><h3>执行处理动作</h3></div>'+select(arbEditorActions(),r.action,'class="arb-action-select" aria-label="处理动作" onchange="arbCurrent().action=this.value;arbRefresh()"')+field('业务说明（选填）','<textarea aria-label="仲裁业务说明" oninput="arbCurrent().note=this.value">'+esc(r.note||'')+'</textarea>')+'<div class="arb-rule-explanation"><h3>规则释义</h3><p>当 '+arbDescribe(r.when)+'，则 <strong>'+esc(ARB_ACTIONS[r.action])+'</strong>。</p></div></div><footer class="merge-drawer-foot"><div class="actions">'+btn('取消','arbCloseEditor()')+btn('保存仲裁规则','arbSaveEditor()','primary')+'</div></footer></section></div>'}
function arbCloseEditor(){arbEditing=null;render();focusAfterDrawerClose('#arbAddButton')}
function arbSaveEditor(){if(!arbEditing)return;let target=arbConfig(),r=clone(arbEditing.rule);r.name=r.name.trim()||'新仲裁规则';let i=target.rules.findIndex(x=>x.id===arbEditing.originalId);if(i>=0&&!arbEditing.isNew)target.rules[i]=r;else target.rules.push(r);arbEditing=null;render();toast('仲裁规则已加入当前合并规则')}
function arbCommitDelete(id){arbConfig().rules=arbConfig().rules.filter(r=>r.id!==id);if(arbEditing?.originalId===id)arbEditing=null;closeModal();render()}
function refreshArbList(){let el=$('#arbListRows');if(el)el.innerHTML=arbTableRows()}
function arbTableRows(){let cfg=arbConfig(),rows=cfg.rules.map((r,i)=>({r,i})).filter(({r})=>!arbListQuery||r.name.includes(arbListQuery));return table(['序号','规则名称','条件数','执行动作','状态','操作'],rows.map(({r,i})=>['<span class="mono">'+String(i+1).padStart(2,'0')+'</span>','<button class="inline-link" onclick="arbChoose(\''+r.id+'\')">'+esc(r.name)+'</button>',arbCount(r.when)+' 个',esc(ARB_ACTIONS[r.action]),switcher(r.enabled,"arbConfig().rules.find(r=>r.id==='"+r.id+"').enabled=this.checked",'启用 '+r.name),'<div class="merge-row-actions">'+btn('编辑',"arbChoose('"+r.id+"')",'text')+btn('复制',"arbDuplicate('"+r.id+"')",'text')+btn('删除',"arbDeleteRule('"+r.id+"')",'text')+'</div>']))+(!rows.length?empty('暂无仲裁规则',''):'')+'<div class="pagination"><span>共 '+rows.length+' 条</span></div>'}
let mergeRuleTab='primary',mergeFocusTab=false;
function mergeTabFor(r=route){return r.startsWith('rule-')?r.slice(5):mergeRuleTab}
function mergeRuleWorkspace(content){let tab=mergeTabFor(),tabs=[['base','基本信息'],...RULES.map(r=>[r[0],r[1]])];return '<div class="merge-rule-tabs" role="tablist" aria-label="合并规则分类">'+tabs.map(([key,label],i)=>'<button id="merge-tab-'+key+'" class="merge-rule-tab '+(tab===key?'active':'')+'" type="button" role="tab" aria-selected="'+(tab===key)+'" aria-controls="merge-rule-content" tabindex="'+(tab===key?'0':'-1')+'" onclick="go(\''+('rule-'+key)+'\')" onkeydown="mergeTabKey(event,'+i+')">'+label+'</button>').join('')+'</div><section id="merge-rule-content" role="tabpanel" aria-labelledby="merge-tab-'+tab+'">'+content+'</section>'}
function mergeTabKey(e,i){let keys=['base',...RULES.map(r=>r[0])],next=i;if(e.key==='ArrowRight')next=(i+1)%keys.length;else if(e.key==='ArrowLeft')next=(i+keys.length-1)%keys.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=keys.length-1;else return;e.preventDefault();mergeFocusTab=true;go('rule-'+keys[next])}
function configFooter(){return ""}
function configHead(){return ""}
function primaryPage(){return ruleQueryModule('primary','判定条件')+contentModule('主客户判定',body('<p class="primary-order-note">按序号从上到下判定，停用条件不参与。</p><div id="primaryRuleRows">'+configDraft.primary.map((r,i)=>'<div class="priority-row">'+primaryOrderControl(r,i)+''+switcher(r.enabled,'configDraft.primary['+i+'].enabled=this.checked',r.name)+'<div class="flex1"><h3>'+esc(r.name)+'</h3><p class="tiny muted" style="margin-top:5px">'+esc(r.note)+'</p></div><div class="actions"><span class="tiny muted">双方均满足</span>'+select(['看下一级','进入订单仲裁','推人工审核'],r.conflict,'aria-label="冲突处理" onchange="configDraft.primary['+i+'].conflict=this.value"')+btn('编辑','editPrimary('+i+')','text')+'</div></div>').join('')+'</div>'),btn('添加判定条件','editPrimary(-1)','primary','plus'))}
function primaryOrderControl(r,i){return '<div class="primary-order-control" data-primary-position="'+i+'"><span class="primary-order-seq" aria-label="序号 '+(i+1)+'">'+String(i+1).padStart(2,'0')+'</span><div class="primary-order-arrows">'+[-1,1].map(delta=>{let direction=delta<0?'up':'down',label=delta<0?'上移':'下移',disabled=i+delta<0||i+delta>=configDraft.primary.length;return '<button type="button" class="primary-move-btn" data-primary-move="'+direction+'" title="'+label+'" aria-label="'+esc(label+' '+r.name)+'" '+(disabled?'disabled ':'')+'onclick="movePrimaryRule('+i+','+(i+delta)+')"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="'+(delta<0?'M12 19V5m-6 6 6-6 6 6':'M12 5v14m-6-6 6 6 6-6')+'"/></svg></button>'}).join('')+'</div></div>'}
function movePrimaryRule(from,to){if(!mergeEditor||!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>=configDraft.primary.length||to>=configDraft.primary.length||from===to)return;let [rule]=configDraft.primary.splice(from,1);configDraft.primary.splice(to,0,rule);render();let control=$('[data-primary-position="'+to+'"]'),direction=to<from?'up':'down',focus=control?.querySelector('[data-primary-move="'+direction+'"]:not(:disabled)')||control?.querySelector('button:not(:disabled)');focus?.focus({preventScroll:true});toast('判定顺序已调整，保存规则后生效')}
function editPrimary(i){let r=configDraft.primary[i]||{name:'',field:'进行中订单数',logic:'大于0',conflict:'看下一级',enabled:true,note:''};modal(i<0?'添加判定条件':'编辑判定条件','<div class="form-stack">'+field('条件名称','<input id="editName" value="'+esc(r.name)+'">',true)+'<div class="form-grid">'+field('判定字段',select(['进行中订单数','手机号','加微记录数','建档时间'],r.field,'id="editField"'))+field('判定逻辑',select(['大于0','不为空','更早','更大'],r.logic,'id="editLogic"'))+'</div>'+field('双方都满足时',select(['看下一级','进入订单仲裁','推人工审核'],r.conflict,'id="editConflict"'))+field('启用状态','<label class="check-line"><input type="checkbox" id="editEnabled" '+(r.enabled?'checked':'')+'>启用此条件</label>')+field('规则说明','<textarea id="editNote">'+esc(r.note)+'</textarea>')+'</div>',btn('取消','closeModal()')+btn('保存条件','commitPrimary('+i+')','primary'))}
function commitPrimary(i){if(!$('#editName').value.trim())$('#editName').value='示例条件';let r={name:$('#editName').value.trim(),field:$('#editField').value,logic:$('#editLogic').value,conflict:$('#editConflict').value,enabled:$('#editEnabled').checked,note:$('#editNote').value};if(i<0)configDraft.primary.push(r);else configDraft.primary[i]=r;closeModal();render();toast('条件已更新，保存并生效后应用')}
function interceptPage(){let a=configDraft.intercept;return ruleQueryModule('intercept','拦截条件')+contentModule('前置拦截条件','<div id="interceptRuleRows">'+table(['序号','状态','拦截条件','判定参数','近30天命中','操作'],a.map((r,i)=>[i+1,switcher(r.on,'configDraft.intercept['+i+'].on=this.checked;render()',r.name),'<strong>'+esc(r.name)+'</strong><div class="muted">'+esc(r.reason)+'</div>',i===0?'阈值 '+numberInput('configDraft.intercept[0].value',r.value,70)+' 个及以上':i===2?'近 '+numberInput('configDraft.intercept[2].value',r.value,70)+' 个月':esc(r.condition)+(r.condition==='状态=指定值'?' · '+r.value:''),'<span class="mono">'+r.hits+'</span> 次',btn('编辑','editIntercept('+i+')','text')+' <span class="muted">·</span> '+btn('查看命中','viewHits('+i+')','text')]))+'</div>',btn('添加拦截条件','editIntercept(-1)','primary','plus'))}
function numberInput(path,value,width=110,min=1){return '<input type="number" min="'+min+'" value="'+value+'" style="width:'+width+'px" aria-label="配置参数" onchange="'+path+'=Number(this.value)">'}
function editIntercept(i){let r=configDraft.intercept[i]||{name:'',field:'白条余额',condition:'不为零',value:0,on:true,reason:'',hits:0};modal(i<0?'添加拦截条件':'编辑拦截条件','<div class="form-stack">'+field('条件名称','<input id="editName" value="'+esc(r.name)+'">',true)+notice('检查对象：子客户（固定）')+'<div class="form-grid">'+field('检查字段',select(['白条余额','充值记录','已完成订单数','进行中投诉数','进行中售后/申述工单数','进行中订单状态','手机号关联客户数'],r.field,'id="editField"'))+field('判定条件',select(['≥阈值','不为零','存在即拦截','状态=指定值','有余额或时间窗口内有记录'],r.condition,'id="editCondition"'))+field('参数值','<input id="editValue" value="'+esc(r.value)+'">')+field('状态','<label class="check-line"><input type="checkbox" id="editEnabled" '+(r.on?'checked':'')+'>启用此条件</label>')+'</div>'+field('拦截原因（展示给审核人）','<textarea id="editNote">'+esc(r.reason)+'</textarea>',true)+'</div>',btn('取消','closeModal()')+btn('保存条件','commitIntercept('+i+')','primary'))}
function commitIntercept(i){if(!$('#editName').value.trim())$('#editName').value='示例条件';if(!$('#editNote').value.trim())$('#editNote').value='示例：按业务需要配置';let val=$('#editValue').value,cond=$('#editCondition').value;if(!val)val='1';let r={name:$('#editName').value,field:$('#editField').value,condition:cond,value:val,on:$('#editEnabled').checked,reason:$('#editNote').value,hits:configDraft.intercept[i]?.hits||0};if(i<0)configDraft.intercept.push(r);else configDraft.intercept[i]=r;closeModal();render()}
function viewHits(i){let r=configDraft.intercept[i];modal('近 30 天命中记录 · '+esc(r.name),notice('累计命中 '+r.hits+' 次，以下展示最近的示例记录。')+table(['触发时间','主 / 子档案','触发场景','处理结果'],Array.from({length:Math.min(5,r.hits)},(_,j)=>['2026-10-'+(15-j)+' 10:2'+j,'CUS-'+(10086+j)+' / CUS-'+(20099+j),['录入手机号','企微加微','创建订单'][j%3],badge(j%2?'已审核':'待审核',j%2?'green':'orange')])),'',true)}
function depositPage(){return queryModule('<div class="search">'+icon('search')+'<input aria-label="搜索预约金仲裁规则" placeholder="搜索预约金仲裁规则名称" value="'+esc(depositPolicyQuery)+'" oninput="depositPolicyQuery=this.value;refreshDepositPolicyRows()"></div>'+btn('重置',"depositPolicyQuery='';render()",'text'))+contentModule('有效期配置',table(['成员状态','有效期','超期处理'],[['<strong>在职成员</strong>','<div class="input-with-unit"><input type="number" min="0" aria-label="在职成员有效期" value="'+configDraft.deposit.active+'" oninput="configDraft.deposit.active=Number(this.value)"><span>个月</span></div>','视为无保护权益'],['<strong>离职成员</strong>','<div class="input-with-unit"><input type="number" min="0" aria-label="离职成员有效期" value="'+configDraft.deposit.left+'" oninput="configDraft.deposit.left=Number(this.value)"><span>个月</span></div>','视为无保护权益']]))+contentModule('三级预约金仲裁','<div id="depositPolicyRows">'+depositPolicyRows()+'</div>')}
const ARB_ACTIONS={keepMain:'保留主订单，流退子订单',keepChild:'保留子订单，流退主订单',keepBoth:'两笔订单都保留',manual:'转人工审核',intercept:'触发前置拦截，转人工审核',latest:'保留最近支付预约金的一方',earliest:'保留最先支付预约金的一方',valid:'保留预约金有效的一方',childHistory:'保留子订单，主超时订单作为历史保留',validity:'按预约金有效期仲裁',continue:'继续匹配下一条规则'};
let arbSelectedId='arb-2';
function arbConfig(){return configDraft.arbitration}
function arbCurrent(){if(arbEditing)return arbEditing.rule;let c=arbConfig();let r=c.rules.find(x=>x.id===arbSelectedId)||c.rules[0];if(r)arbSelectedId=r.id;return r}
function arbCount(n){return n.children?n.children.reduce((s,c)=>s+arbCount(c),0):1}
function arbNode(path){let n=arbCurrent().when;if(path)path.split('.').forEach(i=>n=n.children[+i]);return n}
function arbRefresh(){render()}
function arbChoose(id){let r=arbConfig().rules.find(x=>x.id===id);if(!r)return;arbSelectedId=id;arbEditing={originalId:id,isNew:false,rule:clone(r)};render();$('#arbRuleName')?.focus()}
function arbitrationPage(){return queryModule('<div class="search">'+icon('search')+'<input aria-label="搜索仲裁规则" placeholder="搜索仲裁规则名称" value="'+esc(arbListQuery)+'" oninput="arbListQuery=this.value;refreshArbList()"></div>'+btn('重置',"arbListQuery='';render()",'text'))+contentModule('仲裁规则','<div class="arbitration-fallback">'+field('未命中规则时',select([['manual','转人工审核'],['keepMain','保留主订单，流退子订单'],['keepChild','保留子订单，流退主订单'],['keepBoth','两笔订单都保留']],arbConfig().fallback,'aria-label="订单仲裁未命中规则处理动作" onchange="arbConfig().fallback=this.value"'))+'</div><div id="arbListRows">'+arbTableRows()+'</div>','<button id="arbAddButton" class="btn primary" onclick="arbAddRule()">'+icon('plus')+'新增仲裁规则</button>')}
function arbOperators(f,mode='value'){let type=ARB_FIELDS[f]?.type;return type==='number'?['eq','ne','gt','gte','lt','lte']:type==='date'?['eq','ne','before','after']:mode==='field'?['eq','ne']:['eq','ne','in','notin']}
function arbDefaultValue(field){let f=ARB_FIELDS[field];return f.type==='number'?0:f.type==='date'?'2026-10-15':f.values[0]}
function arbCompatibleFields(field){let f=ARB_FIELDS[field];return Object.entries(ARB_FIELDS).filter(([k,v])=>k!==field&&v.type===f.type&&(f.type!=='enum'||JSON.stringify(v.values)===JSON.stringify(f.values))).map(([k,v])=>[k,v.label])}
function arbRenderGroup(g,path,depth){let pathq="'"+path+"'",root=path==='';return '<div class="arb-group '+(g.join==='any'?'is-any':'')+'" data-group-path="'+path+'"><div class="arb-group-head"><div class="row"><span class="arb-join-word">'+(g.join==='all'?'且':'或')+'</span>'+select([['all','全部条件满足（AND）'],['any','任一条件满足（OR）']],g.join,'aria-label="'+(root?'根条件组':'子条件组')+'匹配方式" onchange="arbNode('+esc(pathq)+').join=this.value;arbRefresh()"')+'</div><div class="actions">'+btn('添加条件','arbAddNode('+pathq+',false)','text','plus')+(depth<2?btn('添加条件组','arbAddNode('+pathq+',true)','text','layers'):'')+(!root?'<button class="icon-btn" aria-label="删除条件组" onclick="arbRemoveNode('+esc(pathq)+')">'+icon('close')+'</button>':'')+'</div></div><div class="arb-group-body">'+(g.children.length?g.children.map((n,i)=>{let p=path?path+'.'+i:String(i);return (i?'<div class="arb-connector">'+(g.join==='all'?'且':'或')+'</div>':'')+(n.children?arbRenderGroup(n,p,depth+1):arbRenderCondition(n,p))}).join(''):'<div class="arb-empty">'+icon('plus')+'添加主订单、子订单的判断条件，或创建嵌套条件组。</div>')+'</div></div>'}
function arbRenderCondition(c,path){let f=ARB_FIELDS[c.field],q="'"+path+"'",attrs='onchange="arbEdit('+esc(q)+',\'value\',this.value)"',value;if(c.mode==='field')value=select(arbCompatibleFields(c.field),c.value,'aria-label="对比字段" '+attrs);else if(['in','notin'].includes(c.operator))value='<div class="arb-value-chips">'+f.values.map(v=>'<label class="'+(Array.isArray(c.value)&&c.value.includes(v)?'on':'')+'"><input type="checkbox" '+(Array.isArray(c.value)&&c.value.includes(v)?'checked':'')+' onchange="arbToggleValue('+esc(q)+',\''+v+'\',this.checked)">'+v+'</label>').join('')+'</div>';else value=f.type==='enum'?select(f.values,c.value,'aria-label="条件取值" '+attrs):'<input type="'+(f.type==='date'?'date':'number')+'" '+(f.type==='number'?'min="0" step="0.01"':'')+' aria-label="条件取值" value="'+esc(c.value)+'" '+attrs+'>';return '<div class="arb-condition" data-condition-path="'+path+'"><div class="arb-condition-main">'+select(Object.entries(ARB_FIELDS).map(([k,v])=>[k,v.label]),c.field,'aria-label="条件字段" onchange="arbEdit('+esc(q)+',\'field\',this.value)"')+select(arbOperators(c.field,c.mode).map(o=>[o,ARB_OPS[o]]),c.operator,'aria-label="比较方式" onchange="arbEdit('+esc(q)+',\'operator\',this.value)"')+'<button class="icon-btn" aria-label="删除条件" onclick="arbRemoveNode('+esc(q)+')">'+icon('close')+'</button></div><div class="arb-condition-value">'+select([['value','指定值'],['field','对比另一字段']],c.mode,'aria-label="取值方式" onchange="arbEdit('+esc(q)+',\'mode\',this.value)"')+value+'</div></div>'}
function arbEdit(path,key,value){let c=arbNode(path);if(key==='field'){c.field=value;c.mode='value';c.operator='eq';c.value=arbDefaultValue(value)}else if(key==='mode'){c.mode=value;c.operator='eq';c.value=value==='field'?arbCompatibleFields(c.field)[0][0]:arbDefaultValue(c.field)}else if(key==='operator'){c.operator=value;c.value=['in','notin'].includes(value)?(Array.isArray(c.value)?c.value:[c.value]):(Array.isArray(c.value)?c.value[0]??arbDefaultValue(c.field):c.value)}else c.value=c.mode==='value'&&ARB_FIELDS[c.field].type==='number'?(value===''?'':Number(value)):value;arbRefresh()}
function arbToggleValue(path,value,checked){let c=arbNode(path);c.value=checked?[...new Set([...c.value,value])]:c.value.filter(x=>x!==value);arbRefresh()}
function arbAddNode(path,group){arbNode(path).children.push(group?arbGroup('any',[arbLeaf('child.status','eq','已到店')]):arbLeaf('main.status','eq','待排客'));arbRefresh()}
function arbRemoveNode(path){let p=path.split('.'),index=+p.pop();arbNode(p.join('.')).children.splice(index,1);arbRefresh()}
function arbAddRule(){let id='custom-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);arbEditing={originalId:null,isNew:true,rule:{id,name:'',enabled:true,when:arbGroup('all',[arbLeaf('main.status','eq','待排客')]),action:'manual',note:''}};render();$('#arbRuleName')?.focus()}
function arbDuplicate(id){let original=arbConfig().rules.find(r=>r.id===id)||arbCurrent(),r=clone(original);r.id='copy-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);r.name+='（副本）';r.enabled=false;arbEditing={originalId:null,isNew:true,rule:r};render();$('#arbRuleName')?.focus()}
function arbDeleteRule(id){let r=arbConfig().rules.find(r=>r.id===id)||arbCurrent();modal('删除仲裁规则','<p>确认删除“'+esc(r.name)+'”？</p>',btn('取消','closeModal()')+btn('删除',"arbCommitDelete('"+r.id+"')",'danger'))}
function validateArbitration(cfg){let errors=[];cfg.rules.forEach((r,i)=>{const prefix='规则 '+(i+1)+'：';if(!r.name.trim())errors.push(prefix+'请填写名称');if(!ARB_ACTIONS[r.action])errors.push(prefix+'请选择处理动作');function walk(n,depth){if(n.children){if(!n.children.length)errors.push(prefix+'条件组不能为空');if(!['all','any'].includes(n.join))errors.push(prefix+'请选择条件组匹配方式');if(depth>2)errors.push(prefix+'条件组最多嵌套三层');n.children.forEach(x=>walk(x,depth+1));return}let f=ARB_FIELDS[n.field];if(!f){errors.push(prefix+'字段无效');return}if(!arbOperators(n.field,n.mode).includes(n.operator))errors.push(prefix+'比较方式不适用于该字段');if(n.mode==='field'){if(!arbCompatibleFields(n.field).some(([k])=>k===n.value))errors.push(prefix+'请选择兼容的对比字段')}else if(f.type==='number'){if(n.value===''||!Number.isFinite(Number(n.value))||Number(n.value)<0)errors.push(prefix+'金额必须为不小于0的数字')}else if(f.type==='date'){if(!n.value||!Number.isFinite(Date.parse(n.value)))errors.push(prefix+'请填写有效日期')}else if(['in','notin'].includes(n.operator)){if(!Array.isArray(n.value)||!n.value.length||n.value.some(v=>!f.values.includes(v)))errors.push(prefix+'请至少选择一个有效取值')}else if(!f.values.includes(n.value))errors.push(prefix+'请填写有效条件值')}
 walk(r.when,0)});return [...new Set(errors)]}
function resetConfig(type){configDraft[type]=clone(defaults[type]);render();toast('已恢复初始配置')}
function configValid(t){let c=configDraft[t];if(t==='arbitration')return validateArbitration(c)[0]||'';if(t==='primary'&&!c.some(x=>x.enabled))return '至少启用一项判定条件';if(t==='intercept'&&c.some(x=>(x.condition==='≥阈值'||x.condition==='有余额或时间窗口内有记录')&&(!Number.isFinite(+x.value)||+x.value<=0)))return '拦截阈值和时间窗口必须大于0';let vals=t==='deposit'?[c.active,c.left]:t==='threshold'?[c.hours,c.months,c.single,c.total,c.age]:[];if(vals.some(x=>!Number.isFinite(x)||x<=0))return '配置数值必须为大于0的有效数字';return ''}
function saveDraft(){saveMergeProfile()}
function saveConfig(){saveMergeProfile()}
function commitConfig(){saveMergeProfile()}
function historyPage(){let rows=state.history.map((h,i)=>({...h,index:i})).filter(h=>(h.profileId||'merge-profile-1')===historyProfileId).filter(h=>(!historyFilter.module||h.module===historyFilter.module)&&(!historyFilter.user||h.user===historyFilter.user)&&(!historyFilter.from||h.time.slice(0,10)>=historyFilter.from)&&(!historyFilter.to||h.time.slice(0,10)<=historyFilter.to));return queryModule(select([['','全部规则模块'],'基本信息',...RULES.map(x=>x[1]),'合并规则'],historyFilter.module,'aria-label="规则模块" onchange="historyFilter.module=this.value;render()"')+select([['','全部操作人'],...new Set(state.history.map(x=>x.user))],historyFilter.user,'aria-label="操作人" onchange="historyFilter.user=this.value;render()"')+'<input type="date" aria-label="开始日期" value="'+historyFilter.from+'" onchange="historyFilter.from=this.value;render()"><span class="muted">至</span><input type="date" aria-label="结束日期" value="'+historyFilter.to+'" onchange="historyFilter.to=this.value;render()">')+contentModule('变更记录',table(['变更时间','操作人','规则模块','变更摘要','操作'],rows.map(h=>['<span class="mono">'+h.time+'</span>',h.user,h.module,esc(h.summary),btn('查看差异','historyDetail('+h.index+')','text')]))+(!rows.length?empty('暂无匹配的变更记录'):'') )}
function historyDetail(i){let h=state.history[i],a=JSON.stringify(h.before,null,2),b=JSON.stringify(h.after,null,2);modal('规则变更详情',kv({'规则模块':h.module,'变更时间':h.time,'操作人':h.user,'变更说明':esc(h.summary)})+'<hr class="light-divider"><div class="diff-row"><div><h3 class="negative">变更前</h3><pre class="rule-diff" style="background:#fff4f4">'+esc(a)+'</pre></div><div><h3 class="positive">变更后</h3><pre class="rule-diff" style="background:#f0f9f4">'+esc(b)+'</pre></div></div>','',true)}
window.PCModules['customer-rules']=(()=>{
 function redraw(){
  const scroll={};$$('[data-drawer-scroll]').forEach(el=>scroll[el.dataset.drawerScroll]=el.scrollTop);
  const pages={'rule-base':mergeBasePage,'rule-primary':primaryPage,'rule-intercept':interceptPage,'rule-deposit':depositPage,'rule-arbitration':arbitrationPage};
  nav();$('#main').innerHTML=mergeProfileList()+'<div class="app-footer">WEID微动 · 客户档案合并与纠错</div>';
  renderRuleDrawers(mergeEditor?(pages[route]||primaryPage)():null);
  $$('[data-drawer-scroll]').forEach(el=>el.scrollTop=scroll[el.dataset.drawerScroll]||0);
  movePageActions();filterRuleRows('primary',ruleListQueries.primary);filterRuleRows('intercept',ruleListQueries.intercept);
  document.title='规则配置 · WEID微动';
  if(mergeFocusTab){$('#merge-tab-'+mergeTabFor())?.focus();mergeFocusTab=false}
  uiObserveIds();
 }
 function leave(){mergeEditor=null;arbEditing=null;historyProfileId=null;$('#mergeDrawers').replaceChildren();syncDrawerInteraction();uiStopObservingIds()}
 return {
  ready:Promise.resolve().then(()=>PCModules['customer-state'].finishInitialization(()=>{})),redraw,
  render(){mergeEditor=null;arbEditing=null;historyProfileId=null;configDraft=clone(state.config);route='rules';if(location.hash!=='#rules')history.replaceState(null,'','#rules');redraw()},
  go(path,id){if(isMergeRoute(path)&&mergeEditor&&path!=='rules'){route=path;mergeRuleTab=mergeTabFor(path);redraw();return}const hash='#'+path+(id?'?id='+encodeURIComponent(id):'');if(location.hash===hash)redraw();else location.hash=hash;$('#sidebar').classList.remove('open');syncSidebarControls();window.scrollTo(0,0)},leave
 };
})();
